package com.juicyslew.moonstation14.ms14.doors;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.juicyslew.moonstation14.ms14.atmos.monitor.AtmosAlarmSeverity;
import com.juicyslew.moonstation14.ms14.doors.prototype.*;
import com.juicyslew.moonstation14.ms14.prototype.PrototypeManager;
import net.minecraft.resources.ResourceLocation;
import org.junit.jupiter.api.Test;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.LinkedHashMap;
import static org.junit.jupiter.api.Assertions.*;

class FirelockStateTest {
    private JsonObject load(String name){try(var in=new InputStreamReader(getClass().getResourceAsStream("/data/moonstation14/moonstation14/firelock/"+name+".json"),StandardCharsets.UTF_8)){return JsonParser.parseReader(in).getAsJsonObject();}catch(Exception e){throw new RuntimeException(e);}}
    private FirelockData data(){var raw=new LinkedHashMap<ResourceLocation,JsonObject>();for(String id:new String[]{"base_structure","base_firelock","firelock"})raw.put(ResourceLocation.fromNamespaceAndPath("moonstation14",id),load(id));var manager=new PrototypeManager();manager.register(ModFirelocks.TYPE);manager.reload(ModFirelocks.TYPE,raw);return manager.snapshot(ModFirelocks.TYPE).get(ModFirelocks.STANDARD);}
    private void assertProductionResourceRejected(String prototype,String nested,String typo){var raw=new LinkedHashMap<ResourceLocation,JsonObject>();for(String id:new String[]{"base_structure","base_firelock","firelock"})raw.put(ResourceLocation.fromNamespaceAndPath("moonstation14",id),load(id));var target=raw.get(ResourceLocation.fromNamespaceAndPath("moonstation14",prototype));if(nested==null)target.addProperty(typo,true);else{for(String part:nested.split("\\."))target=target.getAsJsonObject(part);target.addProperty(typo,true);}var manager=new PrototypeManager();manager.register(ModFirelocks.TYPE);assertThrows(RuntimeException.class,()->manager.reload(ModFirelocks.TYPE,raw));}
    private FirelockState state(AirlockState.DoorPhase phase,boolean power,boolean lock,boolean pw,boolean tw){return new FirelockState(phase,power,lock,pw,tw,0,0,0);}
    @Test void firelockPryTimeDefaultInheritanceOverrideAndResolvedDuration(){var inherited=data();assertEquals(1.5,inherited.door().pryTimeSeconds());assertEquals(60,FirelockPryService.durationTicks(inherited,false,inherited.handPryTimeModifier()));assertEquals(30,FirelockPryService.durationTicks(inherited,false,1));assertEquals(90,FirelockPryService.durationTicks(inherited,true,inherited.handPryTimeModifier()));assertEquals(45,FirelockPryService.durationTicks(inherited,true,1));var raw=new LinkedHashMap<ResourceLocation,JsonObject>();for(String id:new String[]{"base_structure","base_firelock","firelock"})raw.put(ResourceLocation.fromNamespaceAndPath("moonstation14",id),load(id));raw.get(ResourceLocation.fromNamespaceAndPath("moonstation14","base_firelock")).getAsJsonObject("door").addProperty("pryTimeSeconds",2.25);var manager=new PrototypeManager();manager.register(ModFirelocks.TYPE);manager.reload(ModFirelocks.TYPE,raw);var override=manager.snapshot(ModFirelocks.TYPE).get(ModFirelocks.STANDARD);assertEquals(2.25,override.door().pryTimeSeconds());assertEquals(90,FirelockPryService.durationTicks(override,false,override.handPryTimeModifier()),"resolved pry time drives hand consumer duration");assertEquals(45,FirelockPryService.durationTicks(override,false,1),"resolved pry time drives tool consumer duration");}
     @Test void productionCompositionDefaultsAndRealAlarmableTags(){var d=data();var base=load("base_firelock");assertTrue(base.get("initiallyOpen").getAsBoolean());assertEquals(.45,base.getAsJsonObject("door").get("denyDurationSeconds").getAsDouble());assertEquals(2.0,base.getAsJsonObject("door").get("crushStunSeconds").getAsDouble());assertEquals(.5,base.get("handPryTimeModifier").getAsDouble());assertFalse(load("base_structure").has("door"));assertTrue(d.initiallyOpen());assertFalse(d.bumpOpen());assertTrue(d.clickOpen());assertEquals(5,d.apcPowerReceiver().requestedWatts());assertEquals(3,d.extensionCableReceiver().localReachBlocks());assertEquals(.1,d.door().openTimeOneSeconds());assertEquals(.6,d.door().openTimeTwoSeconds());assertEquals(.1,d.door().closeTimeOneSeconds());assertEquals(.6,d.door().closeTimeTwoSeconds());assertEquals(.45,d.door().denyDurationSeconds());assertEquals(2.1,d.door().crushStunSeconds()+d.door().openTimeOneSeconds());assertEquals(20,d.pressureDifferenceKpa());assertEquals(330,d.temperatureDifferenceK());assertEquals(1.5,d.pryModifier());assertEquals(.5,d.handPryTimeModifier());assertEquals(2,d.pryCooldownSeconds());assertEquals(1,d.retrySeconds());assertEquals(java.util.Set.of("Structure","ForceFixRotations"),d.atmosAlarmableData().sourceTags());assertEquals(java.util.Set.of("AirAlarm","FireAlarm"),d.atmosAlarmableData().syncWith());assertTrue(d.deviceComponents().list().isEmpty(),"Firelock does not own DeviceList");var network=d.deviceComponents().network().orElseThrow();assertTrue(network.transmit(),"BaseFirelock AtmosAlarmable is not receive-only; relay sync requires transmitter support");assertTrue(network.receive());assertTrue(network.requiresPower());assertEquals(ResourceLocation.fromNamespaceAndPath("moonstation14","atmos_devices"),network.networkPrototypeId());assertEquals(ResourceLocation.fromNamespaceAndPath("moonstation14","atmos_monitor"),network.receiveFrequencyPrototypeId().orElseThrow());assertEquals(ResourceLocation.fromNamespaceAndPath("moonstation14","atmos_monitor"),network.transmitFrequencyPrototypeId().orElseThrow());}
    @Test void productionResolverRejectsUnknownRootAndNestedCompositionFields(){assertProductionResourceRejected("firelock",null,"initiallyOpne");assertProductionResourceRejected("base_firelock","door","denyDurationSecond");assertProductionResourceRejected("base_firelock","apcPowerReceiver","requestWatts");assertProductionResourceRejected("base_firelock","extensionCableReceiver","localReachBlock");assertProductionResourceRejected("base_firelock","collision","layre");assertProductionResourceRejected("firelock","deviceComponents.deviceNetwork","requirePower");assertProductionResourceRejected("base_firelock","atmosAlarmable","syncWit");}
    @Test void warningsAreSeparateStrictAndUnavailableRetainsTruth(){var d=data();var s=state(AirlockState.DoorPhase.CLOSED,true,false,false,false);var equality=s.observe(d,new FirelockState.Environment(FirelockState.Observation.AVAILABLE,100,300),new FirelockState.Environment(FirelockState.Observation.AVAILABLE,80,630));assertFalse(equality.locked());var changed=s.observe(d,new FirelockState.Environment(FirelockState.Observation.AVAILABLE,100,300),new FirelockState.Environment(FirelockState.Observation.AVAILABLE,79,630));assertTrue(changed.pressureWarning());assertFalse(changed.temperatureWarning());assertTrue(changed.locked());assertEquals(changed,changed.observe(d,FirelockState.Environment.unavailable(),new FirelockState.Environment(FirelockState.Observation.AVAILABLE,0,0)));var temp=s.observe(d,new FirelockState.Environment(FirelockState.Observation.AVAILABLE,0,0),new FirelockState.Environment(FirelockState.Observation.AVAILABLE,0,331));assertFalse(temp.pressureWarning());assertTrue(temp.temperatureWarning());}
     @Test void ordinaryOpenAlarmAndPryPowerAdmission(){var d=data();var locked=state(AirlockState.DoorPhase.CLOSED,true,true,true,false);assertEquals(locked,locked.alarm(d,AtmosAlarmSeverity.NORMAL,0,false));assertEquals(AirlockState.DoorPhase.OPENING,locked.open(d,0,true).phase());assertEquals(FirelockState.Pry.VETOED,locked.pryVeto(false,false));assertEquals(FirelockState.Pry.ALLOWED,locked.pryVeto(true,false));assertEquals(FirelockState.Pry.ALLOWED,locked.pryVeto(false,true));var off=state(AirlockState.DoorPhase.CLOSED,false,false,false,false);assertEquals(FirelockState.Pry.ALLOWED,off.pryVeto(false,false));}
     @Test void relayAlarmSeverityActionsKeepWarningAndEnvironmentalVetoDistinct(){var d=data();var open=state(AirlockState.DoorPhase.OPEN,true,false,false,false);assertSame(open,open.alarm(d,AtmosAlarmSeverity.WARNING,10,false));assertEquals(AirlockState.DoorPhase.CLOSING_PASSABLE,open.alarm(d,AtmosAlarmSeverity.DANGER,10,false).phase());var closedLocked=state(AirlockState.DoorPhase.CLOSED,true,true,true,false);assertSame(closedLocked,closedLocked.alarm(d,AtmosAlarmSeverity.NORMAL,10,false));var closedClear=state(AirlockState.DoorPhase.CLOSED,true,false,false,false);assertEquals(AirlockState.DoorPhase.OPENING,closedClear.alarm(d,AtmosAlarmSeverity.NORMAL,10,false).phase());}
     @Test void phaseDeadlinesPryCooldownAndImmediateEmergencySeal(){var d=data();var opened=state(AirlockState.DoorPhase.OPEN,false,false,false,false);var closed=opened.emergencyPressureStop(d,10,false);assertEquals(FirelockState.Close.CLOSING,closed.result());assertEquals(AirlockState.DoorPhase.CLOSING_PASSABLE,closed.state().phase());assertFalse(closed.state().passable());assertEquals(22,closed.state().transitionAt());assertEquals(AirlockState.DoorPhase.CLOSING_PASSABLE,closed.state().tick(d,21).phase());assertEquals(AirlockState.DoorPhase.CLOSED,closed.state().tick(d,22).phase());var abort=opened.emergencyPressureStop(d,10,true);assertEquals(FirelockState.Close.ABORTED_OBSTRUCTION,abort.result());assertEquals(AirlockState.DoorPhase.OPEN,abort.state().phase());var pry=state(AirlockState.DoorPhase.CLOSED,false,false,false,false).successfulPry(d,0,true,false);assertEquals(40,pry.pryCooldownUntil());assertEquals(AirlockState.DoorPhase.OPENING_PASSABLE,pry.tick(d,2).phase());assertEquals(pry,pry.emergencyPressureStop(d,39,false).state());}
     @Test void inheritedAnimationDefaultsAndResolvedOverridesDriveMotionWithoutChangingPhysicalStages(){var d=data();assertEquals(.6,d.openingAnimationSeconds());assertEquals(.6,d.closingAnimationSeconds());assertEquals(.1,d.door().openTimeOneSeconds());assertEquals(.6,d.door().openTimeTwoSeconds());var opening=new FirelockController.Presentation(state(AirlockState.DoorPhase.OPENING,false,false,false,false),false,100,102,0,0,net.minecraft.core.Direction.NORTH);assertEquals(0,FirelockMotion.openness(opening,d,100));assertEquals(.5,FirelockMotion.openness(opening,d,106));var secondStage=new FirelockController.Presentation(state(AirlockState.DoorPhase.OPENING_PASSABLE,false,false,false,false),false,100,114,0,0,net.minecraft.core.Direction.NORTH);assertEquals(1,FirelockMotion.openness(secondStage,d,112));var closing=new FirelockController.Presentation(state(AirlockState.DoorPhase.CLOSING_PASSABLE,false,false,false,false),false,100,114,0,0,net.minecraft.core.Direction.NORTH);assertEquals(.5,FirelockMotion.openness(closing,d,106));
         var raw=new LinkedHashMap<ResourceLocation,JsonObject>();for(String id:new String[]{"base_structure","base_firelock","firelock"})raw.put(ResourceLocation.fromNamespaceAndPath("moonstation14",id),load(id));raw.get(ResourceLocation.fromNamespaceAndPath("moonstation14","firelock")).addProperty("openingAnimationSeconds",1.2);raw.get(ResourceLocation.fromNamespaceAndPath("moonstation14","firelock")).addProperty("closingAnimationSeconds",.8);var manager=new PrototypeManager();manager.register(ModFirelocks.TYPE);manager.reload(ModFirelocks.TYPE,raw);var override=manager.snapshot(ModFirelocks.TYPE).get(ModFirelocks.STANDARD);assertEquals(1.2,override.openingAnimationSeconds());assertEquals(.8,override.closingAnimationSeconds());assertEquals(.25,FirelockMotion.openness(opening,override,106));assertEquals(.625,FirelockMotion.openness(closing,override,106));}
     @Test void stageBoundaryAndEmergencyClosureKeepActionMotionClock(){var d=data();long actionAt=100;var opening=state(AirlockState.DoorPhase.OPENING,false,false,false,false);var stage=opening.tick(d,actionAt+2);var first=new FirelockController.Presentation(opening,false,actionAt,actionAt+2,0,0,net.minecraft.core.Direction.NORTH);var second=new FirelockController.Presentation(stage,false,actionAt,stage.transitionAt(),0,0,net.minecraft.core.Direction.NORTH);assertEquals(FirelockMotion.openness(first,d,actionAt+2),FirelockMotion.openness(second,d,actionAt+2));var closing=state(AirlockState.DoorPhase.OPEN,true,false,false,false).emergencyPressureStop(d,actionAt,false).state();var emergency=new FirelockController.Presentation(closing,false,actionAt,closing.transitionAt(),0,0,net.minecraft.core.Direction.SOUTH);assertEquals(.5,FirelockMotion.openness(emergency,d,actionAt+6));var tag=new net.minecraft.nbt.CompoundTag();var controller=new FirelockController();controller.load(tagWithMotion(actionAt));controller.save(tag);assertEquals(actionAt,tag.getLong("FirelockMotionStartedAt"));}
     private net.minecraft.nbt.CompoundTag tagWithMotion(long started){var tag=new net.minecraft.nbt.CompoundTag();tag.putLong("FirelockMotionStartedAt",started);tag.putString("FirelockPhase",AirlockState.DoorPhase.OPENING_PASSABLE.name());tag.putBoolean("FirelockPowered",true);tag.putLong("FirelockRevision",4);return tag;}
}
